const text = "Order ORD-48213 shipped, ORD-50077 pending";

text.match(/ORD-\d{5}/g);  // ["ORD-48213", "ORD-50077"]
for (const m of text.matchAll(/ORD-(\d{5})/g)) console.log(m[1]);
text.replace(/ORD-(\d{5})/g, "#$1");
// "Order #48213 shipped, #50077 pending"

const re = /ORD/g;
re.test(text);  // true  (lastIndex is now 9)
re.test(text);  // true  (second ORD, lastIndex 28)
re.test(text);  // false (no more matches, resets to 0)
